import json,numpy as np
for fn in ['/app/output/red_recenter/meta.json']:
 m=json.load(open(fn)); p=np.array(m['proprio']['now'][8:11]);
 for cam in ['egocentric_mirrored_camera','wrist_cam']:
  c=m['cameras'][cam]; K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']); print(cam)
  for nm,x in [('eef',p),('targetground',[.465,.12,.025]),('redgrip',[.465,.12,.04]),('drillnear',[.43,.06,.06])]:
   v=E[:,:3]@np.array(x)+E[:,3]; pix=K@v; print(nm,pix[:2]/pix[2])
PY

