steps.cmd:
python - <<'PY'
import json,numpy as np
m=json.load(open('/app/output/black_over_bin/meta.json'));d=m['cameras']['egocentric_mirrored_camera'];K=np.array(d['intrinsic_cv']);E=np.array(d['extrinsic_cv']);R=E[:,:3];C=-R.T@E[:,3]
for uv in [(230,175),(240,180),(220,190),(340,260),(150,110),(170,115),(250,200)]:
 ray=R.T@np.linalg.inv(K)@np.array([*uv,1]);
 for z in [.22,.26]:
  p=C+(z-C[2])/ray[2]*ray; print(uv,z,p[:2].round(3))
PY

