import json,numpy as np
m=json.load(open('/app/output/red_inspect_high/meta.json'));d=m['cameras']['over_shoulder_left_camera'];K=np.array(d['intrinsic_cv']);E=np.array(d['extrinsic_cv']);R=E[:,:3];C=-R.T@E[:,3]
for uv in [(875,650),(930,650),(1010,675),(955,620),(1070,650),(810,600),(840,700)]:
 ray=R.T@np.linalg.inv(K)@np.array([*uv,1]);
 for z in [-.85,-.9,-.95,0]:
  p=C+(z-C[2])/ray[2]*ray
  print(uv,z,p[:2].round(3))
